"""Twenty-four original literary contexts, not excerpts from published works.

Four fixed cases per family support close reading of tension, action, limited
perspective, word sense, imagery and cross-text interpretation. No human review
or empirical difficulty calibration is implied by the intended demands.
"""
from english_common import make_item


def bp(skill, method, formula, structure, misconceptions):
    return dict(skill=skill, method=method, formula=formula, structure=structure,
                misconceptions=misconceptions, variants=4)


BLUEPRINTS = {
'rw3-literary-held-tension': bp('central-ideas',
    'Retain the speaker’s competing responses when the final gesture preserves rather than resolves their tension.',
    'attachment + recognition of change + unresolved final gesture -> qualified central idea',
    'An original poem expresses two simultaneous attitudes through concrete images.',
    ['one attitude substitutes for the whole poem','an unresolved gesture becomes a final decision','physical setting replaces the speaker’s response']),
'rw3-literary-action-evidence': bp('textual-evidence',
    'Select the action that directly bears on the stated interpretation rather than an adjacent descriptive detail.',
    'bounded interpretation -> diagnostic action in an exact quotation',
    'An original narrative gives several quotable details but only one directly demonstrates the requested response.',
    ['setting treated as evidence of motive','reported habit substitutes for present action','a related object substitutes for the relevant behavior']),
'rw3-literary-perspective-limit': bp('inferences',
    'Distinguish what the narrator observes from the motive the narrator cannot yet establish.',
    'observed behavior + unavailable explanation -> uncertainty about motive, not certainty about intention',
    'A first-person narrator notices an ambiguous act and explicitly lacks its explanatory context.',
    ['a possible motive becomes an established fact','unavailable information is treated as a negative finding','the narrator’s earlier guess overrides later uncertainty']),
'rw3-literary-context-shade': bp('words-context',
    'Use the action and evaluation surrounding a word to distinguish its literary sense from another familiar sense.',
    'local behavior or stylistic features -> context-specific sense and degree',
    'An original prose scene fixes the intended sense through nearby contrasting details.',
    ['academic or literal sense replaces contextual sense','opposite degree selected','an associated action substitutes for the word’s actual meaning']),
'rw3-literary-final-image': bp('text-purpose',
    'Explain how the last image modifies the significance of the earlier concern instead of merely naming its objects.',
    'earlier concern + final concrete image -> reframed relationship or qualified change',
    'A final image brings two earlier details into a new relationship without asserting complete resolution.',
    ['image summarized without its function','partial accommodation becomes complete resolution','figurative relationship becomes a literal event']),
'rw3-literary-cross-reading': bp('cross-text',
    'Test the commentary against the poem’s actual sequence, conditions and remaining qualifications.',
    'interpretation claim + complete textual evidence -> support, limitation or direction correction',
    'An original poem and an original commentary must be compared, not read as automatically agreeing.',
    ['ending erases earlier qualification','conditional action becomes completed action','a change in direction is overlooked']),
}
FAMILIES = {value['skill']: [name] for name,value in BLUEPRINTS.items()}
STEMS = {
'central-ideas':'Which choice best states the central idea of the poem?',
'inferences':'Which inference about the narrator is most strongly supported by the text?',
'cross-text':'Which assessment of Text 2’s interpretation is best supported by Text 1?',
}


def c(passage,right,wrong,evidence,steps,topic,stem='',genre='original fictional prose',difficulty='hard'):
    return dict(passage=passage,right=right,wrong=wrong,evidence=evidence,steps=steps,
                topic=topic,stem=stem,genre=genre,difficulty=difficulty)


