def make(family, seed):
    blueprint=BLUEPRINTS[family]
    item=dict(CASES[family][seed%4]);genre=item.pop('genre')
    item['stem']=item['stem'] or STEMS[blueprint['skill']]
    result=make_item(family=family,seed=seed,blueprint=blueprint,
                     demands=[blueprint['method'],blueprint['structure']],**item)
    result['qualityMetadata']['passageOrigin']=genre
    result['qualityMetadata']['reviewFlags'].append('literary-interpretation-requires-independent-review')
    return result
